      "description": "在从事了时间长到自己都不想承认的办公室工作后，德里克找到了一个愿意和他一起过他年轻时梦想的田园生活的人，于是两人搬到了他家的小屋，再也没有离开。除了拒绝那些很想买下他们房子的开发商的出价时，伊安和德雷克轮流制定日程，过着既刺激又安宁的生活。尽管——或者说正是由于——他们有着不同点，时间对这对老情侣非常仁慈，他们作为亨福昂贝格利社区的核心成员，过着心满意足的退休生活。",
