      "description": "当埃丝特·戈麦斯正在寻找鬼魂室友时，可怜的苏莱卡因一起不幸的牛头摇摇树「事故」而离世，并恰巧也在同个社区寻找新住处。如今，两人共享一个家，埃丝特正慢慢教苏莱卡适应鬼魂生活、以及在死神手下工作的职涯发展技巧。",
