      "worldId": "ravenwood",
      "image": "/images/families/Aether.jpg",
      "description": "在与一只宠物乌鸦沟通失败后，凯·艾瑟发现自己的肉体形态比预期的要差。这是一个许多家庭都熟悉的故事，但这个故事里有一个不幸的变故，给凯的丈夫埃卡德以及他们的儿子高间都带来了巨大的压力——凯似乎不仅不知道自己已经死了，他也不相信有鬼魂。很尴尬吧？但在当地互助小组的帮助下，以及在家人的关爱下，也许凯会开始看到曙光。",
