      "description": "虽然搬到了一个风景更优美的地方，拉迪波一家仍然过着依赖科技的生活。对芙洛拉和阿约而言，最贴近园艺的活动就是给自己的鲜活室内盆栽浇水——显然，大自然只是他们生活的一个美好布景。但需要额外照料的不只是鲜活室内盆栽。在他们的女儿伊丽丝离开家去追寻充满魔法的生活后，这个家庭内部出现了一道裂隙。面对这份逐渐疏离的沉重关系，拉迪波夫妇必须与女儿建立共识，否则彼此间的隔阂将越来越大。",
