      "worldId": "ondarion",
      "image": "/images/families/Abrantes.jpg",
      "description": "在长子与提比家族的女性继承人成功联姻后，埃尔梅琳达．阿布兰特斯理应能安心退休才对。但她希望家族更上一层楼的野心并未随着岁月一同流逝。在家族政治与权力斗争之间，她正值青春年少的女儿索菲亚往往只是贵族生活的天真旁观者，偶尔也会不小心捕捉到宫廷里本应悄然无声的丑闻。",
