      "chineseName": "三米舒诺",
      "description": "这座城市由四个不同的地区组成：香料市场、时尚区、艺术区与上城区。另外，若您的模拟市民需要逃离生活接触大自然的话，可以去三米舒诺草地，一座藏在摩天大楼群下的大型城市公园。依照模拟市民选择居住的地点，您会拥有风格迥异的城市生活。或许您会发现自己身处于艺术区里窄小、蟑螂横行的工作室公寓里...或您也可能住进位于上城区、由自己设计装潢的顶层豪华公寓，并在屋顶上的三温暖中享受这座城市美到令人屏息的景色。",
