      "name": "Stranger Ville",
      "chineseName": "诡奇小镇",
      "description": "欢迎光临诡奇小镇：「唯一比人还奇怪的就是植物！」诡奇小镇是个宁静的小镇，但有个怪异的问题。这里的居民非常友善，但到了晚上状况就会开始变得有趣。如果你想更了解这个城镇，你可以到当地酒吧寻找聚在那里的军事人员，去当地的图书馆找正在做研究的科学家，在拖车园区旁的珍奇异品店摊位则绝对会有些怪异的小东西供你发掘。",
