      "name": "Britechester",
      "chineseName": "布莱彻斯特",
      "description": "进入历史悠久的布莱彻斯特大学或现代化的狐陵学院就读，揭开人生新篇章吧。学生可以住在宿舍，或校外吉布斯山丘的热情小镇。骑脚踏车探索布莱彻斯特，在学生活动中心打发时间，或是在图书馆进修。出席校园精神洋溢的活动，尽情沉浸在学生的欢庆气息中，并穿着代表学校的服装来展现模拟市民的骄傲。",
