      "description": "\"雪松\"之名源自于被白雪覆盖的松树，乡间的真实美景在这里一览无遗。位于木漏隙光山的山坡之上，这个度假村区域提供绝美的度假租屋，许多雪上运动，粗犷的野生环境，以及让人逃离一切纷扰的祥和温泉澡堂。无论是要在温泉中放松，观赏雪之节庆的盛景，或是踏上登上木漏隙光山顶峰的飒爽旅程，每个人来到这个终年有学的美丽幻境都能找到自己喜爱的活动。",
